import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [resorts, setResorts] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchResorts = async () => {
      try {
        const response = await axios.get('http://localhost:3001/api/ski-resorts');
        console.log('Fetched resorts:', response.data); // Debugging line
        setResorts(response.data);
      } catch (error) {
        console.error('Error fetching resorts:', error);
        setError('Error fetching resorts');
      }
    };

    fetchResorts();
  }, []);

  return (
    <div>
      <h1>Ski Resorts</h1>
      {error && <p>{error}</p>}
      <ul>
        {resorts.map(resort => (
          <li key={resort.slug}>{resort.name}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
